   126→			}
   127→			return runDisable(cmd.OutOrStdout(), useProjectSettings)
   128→		},
   129→	}
   130→
   131→	cmd.Flags().BoolVar(&useProjectSettings, "project", false, "Update settings.json instead of settings.local.json")
   132→	cmd.Flags().BoolVar(&uninstall, "uninstall", false, "Completely remove Entire from this repository")
   133→	cmd.Flags().BoolVar(&force, "force", false, "Skip confirmation prompt (use with --uninstall)")
   134→
   135→	return cmd
   136→}
