   531→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
   532→// Returns true if the caller should exit (i.e., Entire is disabled).
   533→// On error reading settings, defaults to enabled (returns false).
   534→func checkDisabledGuard(w io.Writer) bool {
   535→	enabled, err := IsEnabled()
   536→	if err != nil {
   537→		// Default to enabled on error
   538→		return false
   539→	}
   540→	if !enabled {
   541→		fmt.Fprintln(w, DisabledMessage)
   542→		return true
   543→	}
   544→	return false
   545→}
