   606→	settings.Enabled = true
   607→	if localDev {
   608→		settings.LocalDev = localDev
   609→	}
   610→
   611→	// Set push_sessions option if --skip-push-sessions flag was provided
   612→	if skipPushSessions {
   613→		if settings.StrategyOptions == nil {
