  1108→
  1109→// countShadowBranches returns the number of shadow branches.
  1110→func countShadowBranches() int {
  1111→	branches, err := strategy.ListShadowBranches()
  1112→	if err != nil {
  1113→		return 0
  1114→	}
  1115→	return len(branches)
  1116→}
