  1198→	}
  1199→	count := len(states)
  1200→
  1201→	// Remove the entire directory
  1202→	if err := store.RemoveAll(); err != nil {
  1203→		return 0, fmt.Errorf("failed to remove session states: %w", err)
  1204→	}
  1205→
  1206→	return count, nil
  1207→}
  1208→
  1209→// removeEntireDirectory removes the .entire directory.
  1210→func removeEntireDirectory() error {
  1211→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
  1212→	if err != nil {
  1213→		entireDirAbs = paths.EntireDir
  1214→	}
  1215→	if err := os.RemoveAll(entireDirAbs); err != nil {
