   152→func runEnableWithStrategy(w io.Writer, selectedStrategy string, localDev, _, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, telemetry bool, disableMultisessionWarning bool) error {
   153→	// Map the strategy to internal name if it's a display name
   154→	internalStrategy := selectedStrategy
   155→	if mapped, ok := strategyDisplayToInternal[selectedStrategy]; ok {
   156→		internalStrategy = mapped
   157→	}
   158→
   159→	// Validate the strategy exists
   160→	strat, err := strategy.Get(internalStrategy)
   161→	if err != nil {
   162→		return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", selectedStrategy)
   163→	}
   164→
   165→	// Setup Claude Code hooks
   166→	hooksInstalled, err := setupClaudeCodeHook(localDev, forceHooks)
   167→	if err != nil {
