   184→
   185→	// Load existing settings to preserve other options (like strategy_options.push)
   186→	settings, err := LoadEntireSettings()
   187→	if err != nil {
   188→		// If we can't load, start with defaults
   189→		settings = &EntireSettings{}
   190→	}
   191→	// Update the specific fields
   192→	settings.Strategy = internalStrategy
   193→	settings.LocalDev = localDev
   194→	settings.Enabled = true
   195→
   196→	// Set push_sessions option if --skip-push-sessions flag was provided
   197→	if skipPushSessions {
   198→		if settings.StrategyOptions == nil {
   199→			settings.StrategyOptions = make(map[string]interface{})
   200→		}
   201→		settings.StrategyOptions["push_sessions"] = false
