package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/strategy"

	// Import claudecode to register the agent
	_ "entire.io/cli/cmd/entire/cli/agent/claudecode"
)

const (
	// EntireSettingsFile is the path to the Entire settings file
	EntireSettingsFile = ".entire/settings.json"
	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
	EntireSettingsLocalFile = ".entire/settings.local.json"
)

// EntireSettings represents the .entire/settings.json configuration
type EntireSettings struct {
	// Strategy is the name of the git strategy to use
	Strategy string `json:"strategy"`

	// Agent is the name of the coding agent (e.g., "claude-code", "cursor")
	// When empty, auto-detection is used
	Agent string `json:"agent,omitempty"`

	// AgentAutoDetect controls whether to auto-detect the agent when not explicitly set
	// Defaults to true for backwards compatibility
	AgentAutoDetect *bool `json:"agent_auto_detect,omitempty"`

	// Enabled indicates whether Entire is active. When false, CLI commands
	// show a disabled message and hooks exit silently. Defaults to true.
	Enabled bool `json:"enabled"`

	// LocalDev indicates whether to use "go run" instead of the "entire" binary
	// This is used for development when the binary is not installed
	LocalDev bool `json:"local_dev,omitempty"`

	// LogLevel sets the logging verbosity (debug, info, warn, error).
	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
	// Defaults to "info".
	LogLevel string `json:"log_level,omitempty"`

	// StrategyOptions contains strategy-specific configuration
	StrategyOptions map[string]interface{} `json:"strategy_options,omitempty"`

	// AgentOptions contains agent-specific configuration
	// Keyed by agent name, e.g., {"claude-code": {"ignore_untracked": false}}
	AgentOptions map[string]interface{} `json:"agent_options,omitempty"`

	// Telemetry controls anonymous usage analytics.
	// nil = not asked yet (show prompt), true = opted in, false = opted out
	Telemetry *bool `json:"telemetry,omitempty"`
}

// LoadEntireSettings loads the Entire settings from .entire/settings.json,
// then applies any overrides from .entire/settings.local.json if it exists.
// Returns default settings if neither file exists.
// Works correctly from any subdirectory within the repository.
func LoadEntireSettings() (*EntireSettings, error) {
	settings := &EntireSettings{
		Strategy: strategy.DefaultStrategyName,
		Enabled:  true, // Default to enabled
	}

	// Get absolute paths for settings files
	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
	if err != nil {
		settingsFileAbs = EntireSettingsFile // Fallback to relative
	}
	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
	if err != nil {
		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
	}

	// Load base settings
	data, err := os.ReadFile(settingsFileAbs) //nolint:gosec // path is from AbsPath or constant
	if err != nil {
		if !os.IsNotExist(err) {
			return nil, fmt.Errorf("reading settings file: %w", err)
		}
		// File doesn't exist, continue with defaults
	} else {
		if err := json.Unmarshal(data, settings); err != nil {
			return nil, fmt.Errorf("parsing settings file: %w", err)
		}
	}

	// Apply local overrides if they exist
	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
	if err != nil {
		if !os.IsNotExist(err) {
			return nil, fmt.Errorf("reading local settings file: %w", err)
		}
		// Local file doesn't exist, continue without overrides
	} else {
		if err := mergeSettingsJSON(settings, localData); err != nil {
			return nil, fmt.Errorf("merging local settings: %w", err)
		}
	}

	// Apply defaults if not set
	if settings.Strategy == "" {
		settings.Strategy = strategy.DefaultStrategyName
	}
	settings.Strategy = strategy.NormalizeStrategyName(settings.Strategy)

	return settings, nil
}

// mergeSettingsJSON merges JSON data into existing settings.
// Only non-zero values from the JSON override existing settings.
func mergeSettingsJSON(settings *EntireSettings, data []byte) error {
	// Parse into a map to check which fields are present
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("parsing JSON: %w", err)
	}

	// Override strategy if present and non-empty
	if strategyRaw, ok := raw["strategy"]; ok {
		var s string
		if err := json.Unmarshal(strategyRaw, &s); err != nil {
			return fmt.Errorf("parsing strategy field: %w", err)
		}
		if s != "" {
			settings.Strategy = s
		}
	}

	// Override enabled if present
	if enabledRaw, ok := raw["enabled"]; ok {
		var e bool
		if err := json.Unmarshal(enabledRaw, &e); err != nil {
			return fmt.Errorf("parsing enabled field: %w", err)
		}
		settings.Enabled = e
	}

	// Override local_dev if present
	if localDevRaw, ok := raw["local_dev"]; ok {
		var ld bool
		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
			return fmt.Errorf("parsing local_dev field: %w", err)
		}
		settings.LocalDev = ld
	}

	// Override log_level if present and non-empty
	if logLevelRaw, ok := raw["log_level"]; ok {
		var ll string
		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
			return fmt.Errorf("parsing log_level field: %w", err)
		}
		if ll != "" {
			settings.LogLevel = ll
		}
	}

	// Merge strategy_options if present
	if optionsRaw, ok := raw["strategy_options"]; ok {
		var opts map[string]interface{}
		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
			return fmt.Errorf("parsing strategy_options field: %w", err)
		}
		if settings.StrategyOptions == nil {
			settings.StrategyOptions = opts
		} else {
			for k, v := range opts {
				settings.StrategyOptions[k] = v
			}
		}
	}

	// Override agent if present and non-empty
	if agentRaw, ok := raw["agent"]; ok {
		var a string
		if err := json.Unmarshal(agentRaw, &a); err != nil {
			return fmt.Errorf("parsing agent field: %w", err)
		}
		if a != "" {
			settings.Agent = a
		}
	}

	// Override agent_auto_detect if present
	if autoDetectRaw, ok := raw["agent_auto_detect"]; ok {
		var ad bool
		if err := json.Unmarshal(autoDetectRaw, &ad); err != nil {
			return fmt.Errorf("parsing agent_auto_detect field: %w", err)
		}
		settings.AgentAutoDetect = &ad
	}

	// Merge agent_options if present
	if agentOptsRaw, ok := raw["agent_options"]; ok {
		var opts map[string]interface{}
		if err := json.Unmarshal(agentOptsRaw, &opts); err != nil {
			return fmt.Errorf("parsing agent_options field: %w", err)
		}
		if settings.AgentOptions == nil {
			settings.AgentOptions = opts
		} else {
			for k, v := range opts {
				settings.AgentOptions[k] = v
			}
		}
	}

	// Override telemetry if present
	if telemetryRaw, ok := raw["telemetry"]; ok {
		var t bool
		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
			return fmt.Errorf("parsing telemetry field: %w", err)
		}
		settings.Telemetry = &t
	}

	return nil
}

// SaveEntireSettings saves the Entire settings to .entire/settings.json.
func SaveEntireSettings(settings *EntireSettings) error {
	return saveSettingsToFile(settings, EntireSettingsFile)
}

// SaveEntireSettingsLocal saves the Entire settings to .entire/settings.local.json.
func SaveEntireSettingsLocal(settings *EntireSettings) error {
	return saveSettingsToFile(settings, EntireSettingsLocalFile)
}

func saveSettingsToFile(settings *EntireSettings, filePath string) error {
	// Get absolute path for the file
	filePathAbs, err := paths.AbsPath(filePath)
	if err != nil {
		filePathAbs = filePath // Fallback to relative
	}

	// Ensure directory exists
	dir := filepath.Dir(filePathAbs)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("creating settings directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling settings: %w", err)
	}

	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
		return fmt.Errorf("writing settings file: %w", err)
	}
	return nil
}

// IsEnabled returns whether Entire is currently enabled.
// Returns true by default if settings cannot be loaded.
func IsEnabled() (bool, error) {
	settings, err := LoadEntireSettings()
	if err != nil {
		return true, err
	}
	return settings.Enabled, nil
}

// GetStrategy returns the configured strategy instance.
// Falls back to default if the configured strategy is not found.
//
//nolint:ireturn // Factory pattern requires returning the interface
func GetStrategy() strategy.Strategy {
	settings, err := LoadEntireSettings()
	if err != nil {
		// Fall back to default on error
		logging.Info(context.Background(), "falling back to default strategy - failed to load settings",
			slog.String("error", err.Error()))
		return strategy.Default()
	}

	s, err := strategy.Get(settings.Strategy)
	if err != nil {
		// Fall back to default if strategy not found
		logging.Info(context.Background(), "falling back to default strategy - configured strategy not found",
			slog.String("configured", settings.Strategy),
			slog.String("error", err.Error()))
		return strategy.Default()
	}

	return s
}

// GetAgent returns the configured or detected agent.
// Resolution order:
// 1. Explicit agent in settings
// 2. Auto-detect if enabled (default)
// 3. Fall back to default agent
//
//nolint:ireturn // Factory pattern requires returning the interface
func GetAgent() (agent.Agent, error) {
	settings, err := LoadEntireSettings()
	if err != nil {
		// No settings file, try auto-detect then default
		if ag, detectErr := agent.Detect(); detectErr == nil {
			return ag, nil
		}
		return agent.Default(), nil
	}

	// Explicit agent configured
	if settings.Agent != "" {
		ag, err := agent.Get(agent.AgentName(settings.Agent))
		if err != nil {
			return nil, fmt.Errorf("getting configured agent: %w", err)
		}
		return ag, nil
	}

	// Auto-detect if enabled (default true for backwards compat)
	autoDetect := settings.AgentAutoDetect == nil || *settings.AgentAutoDetect
	if autoDetect {
		if ag, detectErr := agent.Detect(); detectErr == nil {
			return ag, nil
		}
	}

	// Fall back to default
	return agent.Default(), nil
}

// GetAgentOptions returns options for a specific agent.
// Returns nil if the agent has no options configured.
func GetAgentOptions(agentName string) map[string]interface{} {
	settings, err := LoadEntireSettings()
	if err != nil {
		return nil
	}

	if settings.AgentOptions == nil {
		return nil
	}

	if opts, ok := settings.AgentOptions[agentName]; ok {
		if m, ok := opts.(map[string]interface{}); ok {
			return m
		}
	}
	return nil
}

// GetLogLevel returns the configured log level from settings.
// Returns empty string if not configured (caller should use default).
// Note: ENTIRE_LOG_LEVEL env var takes precedence; check it first.
func GetLogLevel() string {
	settings, err := LoadEntireSettings()
	if err != nil {
		return ""
	}
	return settings.LogLevel
}

// IsMultiSessionWarningDisabled checks if multi-session warnings are disabled.
// Returns false (show warnings) by default if settings cannot be loaded or the key is missing.
func IsMultiSessionWarningDisabled() bool {
	settings, err := LoadEntireSettings()
	if err != nil {
		return false // Default: show warnings
	}
	if settings.StrategyOptions == nil {
		return false
	}
	if disabled, ok := settings.StrategyOptions["disable_multisession_warning"].(bool); ok {
		return disabled
	}
	return false
}

package strategy

import (
	"fmt"
	"sort"
	"sync"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[string]Factory)
)

// Factory creates a new strategy instance
type Factory func() Strategy

// Register adds a strategy factory to the registry.
// This is typically called from init() functions in strategy implementations.
func Register(name string, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// Get retrieves a strategy by name.
// Returns an error if the strategy is not registered.
func Get(name string) (Strategy, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown strategy: %s (available: %v)", name, List())
	}

	return factory(), nil
}

// List returns all registered strategy names in sorted order.
func List() []string {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]string, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Strategy name constants
const (
	StrategyNameDual         = "dual"   // Legacy name (auto-commit)
	StrategyNameShadow       = "shadow" // Legacy name (manual-commit)
	StrategyNameManualCommit = "manual-commit"
	StrategyNameAutoCommit   = "auto-commit"
)

// DefaultStrategyName is the name of the default strategy.
// Manual-commit is the recommended strategy for most workflows.
const DefaultStrategyName = StrategyNameManualCommit

// Default returns the default strategy.
// Falls back to returning nil if no strategies are registered.
func Default() Strategy {
	s, err := Get(DefaultStrategyName)
	if err != nil {
		// Fallback: return the first registered strategy
		names := List()
		if len(names) > 0 {
			s, _ = Get(names[0]) //nolint:errcheck // Fallback to first strategy, error already handled above
		}
	}
	return s
}

// NormalizeStrategyName maps legacy strategy names to current names.
// These are the strategy names used during initial development and are kept for backwards
// compatibility
func NormalizeStrategyName(name string) string {
	switch name {
	case StrategyNameDual:
		return StrategyNameAutoCommit
	case StrategyNameShadow:
		return StrategyNameManualCommit
	default:
		return name
	}
}

// IsLegacyStrategyName returns true for names that should be mapped.
func IsLegacyStrategyName(name string) bool {
	return name == StrategyNameDual || name == StrategyNameShadow
}

// Package strategy provides an interface for different git strategies
// that can be used to save and manage Claude Code session changes.
package strategy

import (
	"encoding/json"
	"errors"
	"os"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
)

// ErrNoMetadata is returned when a commit does not have an Entire metadata trailer.
var ErrNoMetadata = errors.New("commit has no entire metadata")

// ErrNoSession is returned when no session info is available.
var ErrNoSession = errors.New("no session info available")

// ErrNotTaskCheckpoint is returned when a rewind point is not a task checkpoint.
var ErrNotTaskCheckpoint = errors.New("not a task checkpoint")

// ErrNotImplemented is returned when a feature is not yet implemented.
var ErrNotImplemented = errors.New("not implemented")

// ShadowBranchConflictError is returned when a shadow branch already exists
// with activity from a different session or worktree.
type ShadowBranchConflictError struct {
	Branch           string    // The shadow branch name (e.g., "entire/abc1234")
	ExistingSession  string    // Session ID of the existing session
	ExistingWorktree string    // Worktree path of the existing session
	LastActivity     time.Time // When the existing session was last active
	CurrentSession   string    // Session ID of the current session attempting to start
	CurrentWorktree  string    // Worktree path of the current session
}

func (e *ShadowBranchConflictError) Error() string {
	return "shadow branch conflict: existing session from different worktree"
}

// SessionIDConflictError is returned when trying to start a new session
// but the shadow branch already has commits from a different session ID.
// This prevents orphaning existing session work.
type SessionIDConflictError struct {
	ExistingSession string // Session ID found in the shadow branch
	NewSession      string // Session ID being initialized
	ShadowBranch    string // The shadow branch name (e.g., "entire/abc1234")
}

func (e *SessionIDConflictError) Error() string {
	return "session ID conflict: shadow branch has commits from a different session"
}

// ExtractToolUseIDFromTaskMetadataDir extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
// Returns empty string if not a task metadata directory.
func ExtractToolUseIDFromTaskMetadataDir(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// SessionInfo contains information about the current session state.
// This is used to generate trailers for linking commits to their AI session.
type SessionInfo struct {
	// SessionID is the session identifier extracted from the latest commit's metadata
	SessionID string

	// Reference is a strategy-specific reference string.
	// For manual-commit strategy: "entire/abc1234" (the shadow branch name)
	// Empty for commit strategy (metadata is in the same commit).
	Reference string

	// CommitHash is the full SHA of the commit containing the session metadata.
	// Empty for commit strategy.
	CommitHash string
}

// RewindPoint represents a point to which the user can rewind.
// This abstraction allows different strategies to use different
// identifiers (commit hashes, branch names, stash refs, etc.)
type RewindPoint struct {
	// ID is the unique identifier for this rewind point
	// (commit hash, branch name, stash ref, etc.)
	ID string

	// Message is the human-readable description/summary
	Message string

	// MetadataDir is the path to the metadata directory
	MetadataDir string

	// Date is when this rewind point was created
	Date time.Time

	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
	IsTaskCheckpoint bool

	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
	ToolUseID string

	// IsLogsOnly indicates this is a commit with session logs but no shadow branch state.
	// The logs can be restored from entire/sessions, but file state requires git checkout.
	IsLogsOnly bool

	// CheckpointID is the stable 12-hex-char identifier for logs-only points.
	// Used to retrieve logs from entire/sessions/<id[:2]>/<id[2:]>/full.jsonl
	// Empty for shadow branch checkpoints (uncommitted).
	CheckpointID id.CheckpointID

	// Agent is the human-readable name of the agent that created this checkpoint
	// (e.g., "Claude Code", "Cursor")
	Agent agent.AgentType

	// SessionID is the session identifier for this checkpoint.
	// Used to distinguish checkpoints from different concurrent sessions.
	SessionID string

	// SessionPrompt is the initial prompt that started this session.
	// Used to help users identify which session a checkpoint belongs to.
	SessionPrompt string

	// SessionCount is the number of sessions in this checkpoint (1 for single-session).
	// Only populated for logs-only points with multi-session checkpoints.
	SessionCount int

	// SessionIDs contains all session IDs when this is a multi-session checkpoint.
	// The last entry is the most recent session (same as SessionID).
	// Only populated for logs-only points with multi-session checkpoints.
	SessionIDs []string

	// SessionPrompts contains the first prompt for each session (parallel to SessionIDs).
	// Used to display context when showing resume commands for multi-session checkpoints.
	SessionPrompts []string
}

// RewindPreview describes what will happen when rewinding to a checkpoint.
// Used to warn users about files that will be modified or deleted.
type RewindPreview struct {
	// FilesToRestore are files from the checkpoint that will be written/restored.
	FilesToRestore []string

	// FilesToDelete are untracked files that will be removed.
	// These are files created after the checkpoint that aren't in the checkpoint tree
	// and weren't present at session start.
	FilesToDelete []string

package cli

