  1224→	if err != nil {
  1225→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
  1226→	}
  1227→	if len(branches) == 0 {
  1228→		return 0, nil
  1229→	}
  1230→	deleted, _, err := strategy.DeleteShadowBranches(branches)
  1231→	return len(deleted), err
