   603→	// Update settings to store the agent choice and strategy
   604→	settings, _ := LoadEntireSettings() //nolint:errcheck // settings defaults are fine
   605→	settings.Agent = string(agentName)
   606→	settings.Enabled = true
   607→	if localDev {
   608→		settings.LocalDev = localDev
   609→	}
   610→
   611→	// Set push_sessions option if --skip-push-sessions flag was provided
   612→	if skipPushSessions {
   613→		if settings.StrategyOptions == nil {
   614→			settings.StrategyOptions = make(map[string]interface{})
   615→		}
   616→		settings.StrategyOptions["push_sessions"] = false
   617→	}
   618→
   619→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   620→	if disableMultisessionWarning {
   621→		if settings.StrategyOptions == nil {
   622→			settings.StrategyOptions = make(map[string]interface{})
   623→		}
   624→		settings.StrategyOptions["disable_multisession_warning"] = true
   625→	}
   626→
   627→	// Set strategy if provided
   628→	if strategyName != "" {
   629→		// Map display name to internal name if needed
   630→		internalStrategy := strategyName
   631→		if mapped, ok := strategyDisplayToInternal[strategyName]; ok {
   632→			internalStrategy = mapped
   633→		}
   634→		// Validate the strategy exists
   635→		if _, err := strategy.Get(internalStrategy); err != nil {
   636→			return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", strategyName)
   637→		}
   638→		settings.Strategy = internalStrategy
