  1118→// checkClaudeCodeHooksInstalled checks if Claude Code hooks are installed.
  1119→func checkClaudeCodeHooksInstalled() bool {
  1120→	ag, err := agent.Get(agent.AgentNameClaudeCode)
  1121→	if err != nil {
  1122→		return false
  1123→	}
  1124→	hookAgent, ok := ag.(agent.HookSupport)
  1125→	if !ok {
  1126→		return false
  1127→	}
  1128→	return hookAgent.AreHooksInstalled()
  1129→}
  1130→
  1131→// checkGeminiCLIHooksInstalled checks if Gemini CLI hooks are installed.
  1132→func checkGeminiCLIHooksInstalled() bool {
  1133→	ag, err := agent.Get(agent.AgentNameGemini)
  1134→	if err != nil {
