    40→func newEnableCmd() *cobra.Command {
    41→	var localDev bool
    42→	var ignoreUntracked bool
    43→	var useLocalSettings bool
    44→	var useProjectSettings bool
    45→	var agentName string
    46→	var strategyFlag string
    47→	var forceHooks bool
    48→	var setupShell bool
    49→	var skipPushSessions bool
    50→	var disableMultisessionWarning bool
    51→	var telemetry bool
    52→
    53→	cmd := &cobra.Command{
    54→		Use:   "enable",
    55→		Short: "Enable Entire",
    56→		Long:  "Enable Entire with interactive setup for session tracking mode",
    57→		RunE: func(cmd *cobra.Command, _ []string) error {
    58→			// Check if we're in a git repository first - this is a prerequisite error,
    59→			// not a usage error, so we silence Cobra's output and use SilentError
    60→			// to prevent duplicate error output in main.go
    61→			if _, err := paths.RepoRoot(); err != nil {
    62→				cmd.SilenceUsage = true
    63→				cmd.SilenceErrors = true
    64→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire enable' from within a git repository.")
    65→				return NewSilentError(errors.New("not a git repository"))
    66→			}
    67→
    68→			if err := validateSetupFlags(useLocalSettings, useProjectSettings); err != nil {
    69→				return err
    70→			}
    71→			// Non-interactive mode if --agent flag is provided
    72→			if agentName != "" {
    73→				return setupAgentHooksNonInteractive(agent.AgentName(agentName), strategyFlag, localDev, forceHooks, skipPushSessions, telemetry, disableMultisessionWarning)
    74→			}
    75→			// If strategy is specified via flag, skip interactive selection
    76→			if strategyFlag != "" {
    77→				return runEnableWithStrategy(cmd.OutOrStdout(), strategyFlag, localDev, ignoreUntracked, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, telemetry, disableMultisessionWarning)
    78→			}
    79→			return runEnableInteractive(cmd.OutOrStdout(), localDev, ignoreUntracked, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, telemetry, disableMultisessionWarning)
    80→		},
    81→	}
