   277→// runEnableInteractive runs the interactive enable flow with strategy selection.
   278→func runEnableInteractive(w io.Writer, localDev, _, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, telemetry, disableMultisessionWarning bool) error {
   279→	// Build strategy options with user-friendly names
   280→	var selectedStrategy string
   281→	options := []huh.Option[string]{
   282→		huh.NewOption(strategyDisplayManualCommit+"  Sessions are only captured when you commit", strategyDisplayManualCommit),
   283→		huh.NewOption(strategyDisplayAutoCommit+"  Automatically capture sessions after agent response completion", strategyDisplayAutoCommit),
   284→	}
   285→
   286→	form := NewAccessibleForm(
   287→		huh.NewGroup(
   288→			huh.NewSelect[string]().
   289→				Options(options...).
   290→				Value(&selectedStrategy),
   291→		),
   292→	)
   293→
   294→	if err := form.Run(); err != nil {
   295→		return fmt.Errorf("selection cancelled: %w", err)
   296→	}
   297→
   298→	// Map display name to internal strategy name
   299→	internalStrategy, ok := strategyDisplayToInternal[selectedStrategy]
   300→	if !ok {
   301→		return fmt.Errorf("unknown strategy: %s", selectedStrategy)
   302→	}
   303→
   304→	// Setup Claude Code hooks
   305→	hooksInstalled, err := setupClaudeCodeHook(localDev, forceHooks)
   306→	if err != nil {
   307→		return fmt.Errorf("failed to setup Claude Code hooks: %w", err)
   308→	}
   309→	if hooksInstalled > 0 {
   310→		fmt.Fprintln(w, "✓ Claude Code hooks installed")
   311→	} else {
   312→		fmt.Fprintln(w, "✓ Claude Code hooks verified")
   313→	}
   314→
   315→	// Setup .entire directory
   316→	dirCreated, err := setupEntireDirectory()
   317→	if err != nil {
   318→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   319→	}
   320→	if dirCreated {
   321→		fmt.Fprintln(w, "✓ .entire directory created")
   322→	}
   323→
   324→	// Load existing settings to preserve other options (like strategy_options.push)
   325→	settings, err := LoadEntireSettings()
   326→	if err != nil {
   327→		// If we can't load, start with defaults
   328→		settings = &EntireSettings{}
   329→	}
   330→	// Update the specific fields
   331→	settings.Strategy = internalStrategy
   332→	settings.LocalDev = localDev
   333→	settings.Enabled = true
   334→
   335→	// Set push_sessions option if --skip-push-sessions flag was provided
   336→	if skipPushSessions {
   337→		if settings.StrategyOptions == nil {
   338→			settings.StrategyOptions = make(map[string]interface{})
   339→		}
   340→		settings.StrategyOptions["push_sessions"] = false
   341→	}
   342→
   343→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   344→	if disableMultisessionWarning {
   345→		if settings.StrategyOptions == nil {
   346→			settings.StrategyOptions = make(map[string]interface{})
   347→		}
   348→		settings.StrategyOptions["disable_multisession_warning"] = true
   349→	}
   350→
   351→	// Ask about telemetry consent (only if not already asked)
   352→	if err := promptTelemetryConsent(settings, telemetry); err != nil {
   353→		return fmt.Errorf("telemetry consent: %w", err)
   354→	}
   355→
   356→	// Determine which settings file to write to (interactive prompt if settings.json exists)
   357→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   358→	if err != nil {
   359→		entireDirAbs = paths.EntireDir // Fallback to relative
   360→	}
   361→	shouldUseLocal, err := promptSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   362→	if err != nil {
   363→		return err
   364→	}
   365→
   366→	if shouldUseLocal {
   367→		if err := SaveEntireSettingsLocal(settings); err != nil {
   368→			return fmt.Errorf("failed to save local settings: %w", err)
   369→		}
   370→		fmt.Fprintln(w, "✓ Local settings saved (.entire/settings.local.json)")
   371→	} else {
   372→		if err := SaveEntireSettings(settings); err != nil {
   373→			return fmt.Errorf("failed to save settings: %w", err)
   374→		}
   375→		fmt.Fprintln(w, "✓ Project settings saved (.entire/settings.json)")
   376→	}
   377→
   378→	// Install git hooks (always reinstall to ensure they're up-to-date)
   379→	gitHooksInstalled, err := strategy.InstallGitHook(true)
   380→	if err != nil {
   381→		return fmt.Errorf("failed to install git hooks: %w", err)
   382→	}
   383→	if gitHooksInstalled > 0 {
   384→		fmt.Fprintln(w, "✓ Git hooks installed")
   385→	} else {
   386→		fmt.Fprintln(w, "✓ Git hooks verified")
