   458→func runStatus(w io.Writer) error {
   459→	// Check if we're in a git repository
   460→	if _, repoErr := paths.RepoRoot(); repoErr != nil {
   461→		fmt.Fprintln(w, "✕ not a git repository")
   462→		return nil //nolint:nilerr // Not being in a git repo is a valid status, not an error
   463→	}
   464→
   465→	// Get absolute paths for settings files
   466→	settingsPath, err := paths.AbsPath(EntireSettingsFile)
   467→	if err != nil {
   468→		settingsPath = EntireSettingsFile
   469→	}
   470→	localSettingsPath, err := paths.AbsPath(EntireSettingsLocalFile)
   471→	if err != nil {
   472→		localSettingsPath = EntireSettingsLocalFile
   473→	}
   474→
   475→	// Check which settings files exist (for source label)
   476→	_, projectErr := os.Stat(settingsPath)
   477→	if projectErr != nil && !errors.Is(projectErr, fs.ErrNotExist) {
   478→		return fmt.Errorf("cannot access project settings file: %w", projectErr)
   479→	}
   480→	_, localErr := os.Stat(localSettingsPath)
   481→	if localErr != nil && !errors.Is(localErr, fs.ErrNotExist) {
   482→		return fmt.Errorf("cannot access local settings file: %w", localErr)
   483→	}
   484→	projectExists := projectErr == nil
   485→	localExists := localErr == nil
   486→
   487→	if !projectExists && !localExists {
   488→		fmt.Fprintln(w, "○ not set up (run `entire enable` to get started)")
   489→		return nil
   490→	}
   491→
   492→	// Load merged settings
   493→	settings, err := LoadEntireSettings()
   494→	if err != nil {
   495→		return fmt.Errorf("failed to load settings: %w", err)
   496→	}
   497→	settings.Strategy = strategy.NormalizeStrategyName(settings.Strategy)
   498→
   499→	// Determine source label
   500→	var sourceLabel string
   501→	switch {
   502→	case projectExists && localExists:
   503→		sourceLabel = "Project + Local"
   504→	case localExists:
   505→		sourceLabel = "Local"
   506→	default:
   507→		sourceLabel = "Project"
   508→	}
   509→
   510→	fmt.Fprintln(w, formatSettingsStatus(sourceLabel, settings))
   511→	return nil
   512→}
