    58→			// Check if we're in a git repository first - this is a prerequisite error,
    59→			// not a usage error, so we silence Cobra's output and use SilentError
    60→			// to prevent duplicate error output in main.go
    61→			if _, err := paths.RepoRoot(); err != nil {
    62→				cmd.SilenceUsage = true
    63→				cmd.SilenceErrors = true
