   547→// setupClaudeCodeHook sets up Claude Code hooks.
   548→// This is a convenience wrapper that uses the agent package.
   549→// Returns the number of hooks installed (0 if already installed).
   550→func setupClaudeCodeHook(localDev, forceHooks bool) (int, error) {
   551→	ag, err := agent.Get(agent.AgentNameClaudeCode)
   552→	if err != nil {
   553→		return 0, fmt.Errorf("failed to get claude-code agent: %w", err)
   554→	}
   555→
   556→	hookAgent, ok := ag.(agent.HookSupport)
   557→	if !ok {
   558→		return 0, errors.New("claude-code agent does not support hooks")
   559→	}
   560→
   561→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
   562→	if err != nil {
   563→		return 0, fmt.Errorf("failed to install claude-code hooks: %w", err)
   564→	}
   565→
   566→	return count, nil
