  1154→// removeAgentHooks removes hooks from all agents that support hooks.
  1155→func removeAgentHooks(w io.Writer) error {
  1156→	var errs []error
  1157→
  1158→	// Remove Claude Code hooks
  1159→	claudeAgent, err := agent.Get(agent.AgentNameClaudeCode)
  1160→	if err == nil {
  1161→		if hookAgent, ok := claudeAgent.(agent.HookSupport); ok {
  1162→			wasInstalled := hookAgent.AreHooksInstalled()
  1163→			if err := hookAgent.UninstallHooks(); err != nil {
  1164→				errs = append(errs, err)
  1165→			} else if wasInstalled {
  1166→				fmt.Fprintln(w, "  Removed Claude Code hooks")
  1167→			}
  1168→		}
  1169→	}
  1170→
  1171→	// Remove Gemini CLI hooks
  1172→	geminiAgent, err := agent.Get(agent.AgentNameGemini)
  1173→	if err == nil {
  1174→		if hookAgent, ok := geminiAgent.(agent.HookSupport); ok {
  1175→			wasInstalled := hookAgent.AreHooksInstalled()
  1176→			if err := hookAgent.UninstallHooks(); err != nil {
