   514→// formatSettingsStatus formats a settings status line.
   515→// Output format: "Project, enabled (manual-commit)" or "Local, disabled (auto-commit)"
   516→func formatSettingsStatus(prefix string, settings *EntireSettings) string {
   517→	displayName := settings.Strategy
   518→	if dn, ok := strategyInternalToDisplay[settings.Strategy]; ok {
   519→		displayName = dn
   520→	}
   521→
   522→	if settings.Enabled {
   523→		return fmt.Sprintf("%s, enabled (%s)", prefix, displayName)
   524→	}
   525→	return fmt.Sprintf("%s, disabled (%s)", prefix, displayName)
