   593→		}
   594→		fmt.Println(msg)
   595→	} else {
   596→		msg := fmt.Sprintf("Installed %d hooks for %s", count, ag.Description())
   597→		if agentName == agent.AgentNameGemini {
   598→			msg += " - This is a work in progress"
   599→		}
   600→		fmt.Println(msg)
   601→	}
   602→
   603→	// Update settings to store the agent choice and strategy
   604→	settings, _ := LoadEntireSettings() //nolint:errcheck // settings defaults are fine
