  1186→
  1187→// removeAllSessionStates removes all session state files and the directory.
  1188→func removeAllSessionStates() (int, error) {
  1189→	store, err := session.NewStateStore()
  1190→	if err != nil {
  1191→		return 0, fmt.Errorf("failed to create state store: %w", err)
  1192→	}
  1193→
  1194→	// Count states before removing
  1195→	states, err := store.List(context.Background())
  1196→	if err != nil {
