// checkEntireDirExists checks if the .entire directory exists.
func checkEntireDirExists() bool {
	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
	if err != nil {
		entireDirAbs = paths.EntireDir
	}
	_, err = os.Stat(entireDirAbs)
	return err == nil
}

// removeAgentHooks removes hooks from all agents that support hooks.
func removeAgentHooks(w io.Writer) error {
	var errs []error

	// Remove Claude Code hooks
	claudeAgent, err := agent.Get(agent.AgentNameClaudeCode)
	if err == nil {
		if hookAgent, ok := claudeAgent.(agent.HookSupport); ok {
			wasInstalled := hookAgent.AreHooksInstalled()
			if err := hookAgent.UninstallHooks(); err != nil {
				errs = append(errs, err)
			} else if wasInstalled {
				fmt.Fprintln(w, "  Removed Claude Code hooks")
			}
		}
	}

	// Remove Gemini CLI hooks
	geminiAgent, err := agent.Get(agent.AgentNameGemini)
	if err == nil {
		if hookAgent, ok := geminiAgent.(agent.HookSupport); ok {
			wasInstalled := hookAgent.AreHooksInstalled()
			if err := hookAgent.UninstallHooks(); err != nil {
				errs = append(errs, err)
			} else if wasInstalled {
				fmt.Fprintln(w, "  Removed Gemini CLI hooks")
			}
		}
	}

	return errors.Join(errs...)
}

// removeAllSessionStates removes all session state files and the directory.
func removeAllSessionStates() (int, error) {
	store, err := session.NewStateStore()
	if err != nil {
		return 0, fmt.Errorf("failed to create state store: %w", err)
	}

	// Count states before removing
	states, err := store.List(context.Background())
	if err != nil {
		return 0, fmt.Errorf("failed to list session states: %w", err)
	}
	count := len(states)

	// Remove the entire directory
	if err := store.RemoveAll(); err != nil {
		return 0, fmt.Errorf("failed to remove session states: %w", err)
	}

	return count, nil
}

// removeEntireDirectory removes the .entire directory.
func removeEntireDirectory() error {
	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
	if err != nil {
		entireDirAbs = paths.EntireDir
	}
	if err := os.RemoveAll(entireDirAbs); err != nil {
		return fmt.Errorf("failed to remove .entire directory: %w", err)
	}
	return nil
}

// removeAllShadowBranches removes all shadow branches.
func removeAllShadowBranches() (int, error) {
	branches, err := strategy.ListShadowBranches()
	if err != nil {
		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
	}
	if len(branches) == 0 {
		return 0, nil
	}
	deleted, _, err := strategy.DeleteShadowBranches(branches)
	return len(deleted), err
}

package strategy

import (
	"fmt"
	"sort"
	"sync"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[string]Factory)
)

// Factory creates a new strategy instance
type Factory func() Strategy

// Register adds a strategy factory to the registry.
// This is typically called from init() functions in strategy implementations.
func Register(name string, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// Get retrieves a strategy by name.
// Returns an error if the strategy is not registered.
func Get(name string) (Strategy, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown strategy: %s (available: %v)", name, List())
	}

	return factory(), nil
}

// List returns all registered strategy names in sorted order.
func List() []string {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]string, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Strategy name constants
const (
	StrategyNameDual         = "dual"   // Legacy name (auto-commit)
	StrategyNameShadow       = "shadow" // Legacy name (manual-commit)
	StrategyNameManualCommit = "manual-commit"
	StrategyNameAutoCommit   = "auto-commit"
)

// DefaultStrategyName is the name of the default strategy.
// Manual-commit is the recommended strategy for most workflows.
const DefaultStrategyName = StrategyNameManualCommit

// Default returns the default strategy.
// Falls back to returning nil if no strategies are registered.
func Default() Strategy {
	s, err := Get(DefaultStrategyName)
	if err != nil {
		// Fallback: return the first registered strategy
		names := List()
		if len(names) > 0 {
			s, _ = Get(names[0]) //nolint:errcheck // Fallback to first strategy, error already handled above
		}
	}
	return s
}

// NormalizeStrategyName maps legacy strategy names to current names.
// These are the strategy names used during initial development and are kept for backwards
// compatibility
func NormalizeStrategyName(name string) string {
	switch name {
	case StrategyNameDual:
		return StrategyNameAutoCommit
	case StrategyNameShadow:
		return StrategyNameManualCommit
	default:
		return name
	}
}

// IsLegacyStrategyName returns true for names that should be mapped.
func IsLegacyStrategyName(name string) bool {
	return name == StrategyNameDual || name == StrategyNameShadow
}

