package strategy

import (
	"fmt"
	"sort"
	"sync"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[string]Factory)
)

// Factory creates a new strategy instance
type Factory func() Strategy

// Register adds a strategy factory to the registry.
// This is typically called from init() functions in strategy implementations.
func Register(name string, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// Get retrieves a strategy by name.
// Returns an error if the strategy is not registered.
func Get(name string) (Strategy, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown strategy: %s (available: %v)", name, List())
	}

	return factory(), nil
}

// List returns all registered strategy names in sorted order.
func List() []string {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]string, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Strategy name constants
const (
	StrategyNameDual         = "dual"   // Legacy name (auto-commit)
	StrategyNameShadow       = "shadow" // Legacy name (manual-commit)
	StrategyNameManualCommit = "manual-commit"
	StrategyNameAutoCommit   = "auto-commit"
)

// DefaultStrategyName is the name of the default strategy.
// Manual-commit is the recommended strategy for most workflows.
const DefaultStrategyName = StrategyNameManualCommit

// Default returns the default strategy.
// Falls back to returning nil if no strategies are registered.
func Default() Strategy {
	s, err := Get(DefaultStrategyName)
	if err != nil {
		// Fallback: return the first registered strategy
		names := List()
		if len(names) > 0 {
			s, _ = Get(names[0]) //nolint:errcheck // Fallback to first strategy, error already handled above
		}
	}
	return s
}

// NormalizeStrategyName maps legacy strategy names to current names.
// These are the strategy names used during initial development and are kept for backwards
// compatibility
func NormalizeStrategyName(name string) string {
	switch name {
	case StrategyNameDual:
		return StrategyNameAutoCommit
	case StrategyNameShadow:
		return StrategyNameManualCommit
	default:
		return name
	}
}

// IsLegacyStrategyName returns true for names that should be mapped.
func IsLegacyStrategyName(name string) bool {
	return name == StrategyNameDual || name == StrategyNameShadow
}

