  1144→// checkEntireDirExists checks if the .entire directory exists.
  1145→func checkEntireDirExists() bool {
  1146→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
  1147→	if err != nil {
  1148→		entireDirAbs = paths.EntireDir
