  1153→
  1154→// removeAgentHooks removes hooks from all agents that support hooks.
  1155→func removeAgentHooks(w io.Writer) error {
  1156→	var errs []error
  1157→
  1158→	// Remove Claude Code hooks
  1159→	claudeAgent, err := agent.Get(agent.AgentNameClaudeCode)
  1160→	if err == nil {
  1161→		if hookAgent, ok := claudeAgent.(agent.HookSupport); ok {
  1162→			wasInstalled := hookAgent.AreHooksInstalled()
  1163→			if err := hookAgent.UninstallHooks(); err != nil {
  1164→				errs = append(errs, err)
  1165→			} else if wasInstalled {
  1166→				fmt.Fprintln(w, "  Removed Claude Code hooks")
  1167→			}
  1168→		}
  1169→	}
  1170→
  1171→	// Remove Gemini CLI hooks
  1172→	geminiAgent, err := agent.Get(agent.AgentNameGemini)
  1173→	if err == nil {
  1174→		if hookAgent, ok := geminiAgent.(agent.HookSupport); ok {
  1175→			wasInstalled := hookAgent.AreHooksInstalled()
  1176→			if err := hookAgent.UninstallHooks(); err != nil {
  1177→				errs = append(errs, err)
  1178→			} else if wasInstalled {
  1179→				fmt.Fprintln(w, "  Removed Gemini CLI hooks")
  1180→			}
  1181→		}
  1182→	}
  1183→
  1184→	return errors.Join(errs...)
  1185→}
  1186→
  1187→// removeAllSessionStates removes all session state files and the directory.
  1188→func removeAllSessionStates() (int, error) {
  1189→	store, err := session.NewStateStore()
  1190→	if err != nil {
  1191→		return 0, fmt.Errorf("failed to create state store: %w", err)
  1192→	}
  1193→
  1194→	// Count states before removing
  1195→	states, err := store.List(context.Background())
  1196→	if err != nil {
  1197→		return 0, fmt.Errorf("failed to list session states: %w", err)
  1198→	}
  1199→	count := len(states)
  1200→
  1201→	// Remove the entire directory
  1202→	if err := store.RemoveAll(); err != nil {
  1203→		return 0, fmt.Errorf("failed to remove session states: %w", err)
  1204→	}
  1205→
  1206→	return count, nil
  1207→}
  1208→
  1209→// removeEntireDirectory removes the .entire directory.
  1210→func removeEntireDirectory() error {
  1211→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
  1212→	if err != nil {
  1213→		entireDirAbs = paths.EntireDir
  1214→	}
  1215→	if err := os.RemoveAll(entireDirAbs); err != nil {
  1216→		return fmt.Errorf("failed to remove .entire directory: %w", err)
  1217→	}
  1218→	return nil
  1219→}
  1220→
  1221→// removeAllShadowBranches removes all shadow branches.
  1222→func removeAllShadowBranches() (int, error) {
  1223→	branches, err := strategy.ListShadowBranches()
  1224→	if err != nil {
  1225→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
  1226→	}
  1227→	if len(branches) == 0 {
  1228→		return 0, nil
  1229→	}
  1230→	deleted, _, err := strategy.DeleteShadowBranches(branches)
  1231→	return len(deleted), err
  1232→}
