   400→func TestRunEnableWithStrategy_PreservesExistingSettings(t *testing.T) {
   401→	setupTestRepo(t)
   402→
   403→	// Create initial settings with strategy_options (like push enabled)
   404→	initialSettings := `{
   405→		"strategy": "manual-commit",
   406→		"enabled": true,
   407→		"strategy_options": {
   408→			"push": true,
   409→			"some_other_option": "value"
   410→		},
   411→		"agent_options": {
   412→			"claude-code": {
   413→				"ignore_untracked": true
   414→			}
   415→		}
   416→	}`
   417→	writeSettings(t, initialSettings)
   418→
   419→	// Run enable with a different strategy
   420→	var stdout bytes.Buffer
   421→	err := runEnableWithStrategy(&stdout, "auto-commit", false, false, false, true, false, false, false, false, false)
   422→	if err != nil {
   423→		t.Fatalf("runEnableWithStrategy() error = %v", err)
   424→	}
   425→
   426→	// Load the saved settings and verify strategy_options were preserved
   427→	settings, err := LoadEntireSettings()
   428→	if err != nil {
   429→		t.Fatalf("LoadEntireSettings() error = %v", err)
   430→	}
   431→
   432→	// Strategy should be updated
   433→	if settings.Strategy != "auto-commit" {
   434→		t.Errorf("Strategy should be 'auto-commit', got %q", settings.Strategy)
   435→	}
   436→
   437→	// strategy_options should be preserved
   438→	if settings.StrategyOptions == nil {
   439→		t.Fatal("strategy_options should be preserved, but got nil")
   440→	}
   441→	if settings.StrategyOptions["push"] != true {
   442→		t.Errorf("strategy_options.push should be true, got %v", settings.StrategyOptions["push"])
   443→	}
   444→	if settings.StrategyOptions["some_other_option"] != "value" {
   445→		t.Errorf("strategy_options.some_other_option should be 'value', got %v", settings.StrategyOptions["some_other_option"])
   446→	}
   447→
   448→	// agent_options should be preserved
   449→	if settings.AgentOptions == nil {
   450→		t.Fatal("agent_options should be preserved, but got nil")
   451→	}
   452→	claudeOpts, ok := settings.AgentOptions["claude-code"].(map[string]interface{})
   453→	if !ok {
   454→		t.Fatal("agent_options.claude-code should exist")
   455→	}
   456→	if claudeOpts["ignore_untracked"] != true {
   457→		t.Errorf("agent_options.claude-code.ignore_untracked should be true, got %v", claudeOpts["ignore_untracked"])
   458→	}
   459→}
