   985→// runUninstall completely removes Entire from the repository.
   986→func runUninstall(w, errW io.Writer, force bool) error {
   987→	// Check if we're in a git repository
   988→	if _, err := paths.RepoRoot(); err != nil {
   989→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
   990→		return NewSilentError(errors.New("not a git repository"))
   991→	}
   992→
   993→	// Gather counts for display
   994→	sessionStateCount := countSessionStates()
   995→	shadowBranchCount := countShadowBranches()
   996→	gitHooksInstalled := strategy.IsGitHookInstalled()
   997→	claudeHooksInstalled := checkClaudeCodeHooksInstalled()
   998→	geminiHooksInstalled := checkGeminiCLIHooksInstalled()
   999→	entireDirExists := checkEntireDirExists()
  1000→
  1001→	// Check if there's anything to uninstall
  1002→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
  1003→		shadowBranchCount == 0 && !claudeHooksInstalled && !geminiHooksInstalled {
  1004→		fmt.Fprintln(w, "Entire is not installed in this repository.")
  1005→		return nil
  1006→	}
  1007→
  1008→	// Show confirmation prompt unless --force
  1009→	if !force {
  1010→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
  1011→		if entireDirExists {
  1012→			fmt.Fprintln(w, "  - .entire/ directory")
  1013→		}
  1014→		if gitHooksInstalled {
  1015→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
  1016→		}
  1017→		if sessionStateCount > 0 {
  1018→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
  1019→		}
  1020→		if shadowBranchCount > 0 {
  1021→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
  1022→		}
  1023→		switch {
  1024→		case claudeHooksInstalled && geminiHooksInstalled:
  1025→			fmt.Fprintln(w, "  - Agent hooks (Claude Code, Gemini CLI)")
  1026→		case claudeHooksInstalled:
  1027→			fmt.Fprintln(w, "  - Agent hooks (Claude Code)")
  1028→		case geminiHooksInstalled:
  1029→			fmt.Fprintln(w, "  - Agent hooks (Gemini CLI)")
  1030→		}
  1031→		fmt.Fprintln(w)
  1032→
  1033→		var confirmed bool
  1034→		form := NewAccessibleForm(
  1035→			huh.NewGroup(
  1036→				huh.NewConfirm().
  1037→					Title("Are you sure you want to uninstall Entire?").
  1038→					Affirmative("Yes, uninstall").
  1039→					Negative("Cancel").
  1040→					Value(&confirmed),
  1041→			),
  1042→		)
  1043→
  1044→		if err := form.Run(); err != nil {
  1045→			return fmt.Errorf("confirmation cancelled: %w", err)
  1046→		}
  1047→
  1048→		if !confirmed {
  1049→			fmt.Fprintln(w, "Uninstall cancelled.")
  1050→			return nil
  1051→		}
  1052→	}
  1053→
  1054→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
  1055→
  1056→	// 1. Remove agent hooks (lowest risk)
  1057→	if err := removeAgentHooks(w); err != nil {
  1058→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
  1059→	}
  1060→
  1061→	// 2. Remove git hooks
  1062→	removed, err := strategy.RemoveGitHook()
  1063→	if err != nil {
  1064→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
  1065→	} else if removed > 0 {
  1066→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
  1067→	}
  1068→
  1069→	// 3. Remove session state files
  1070→	statesRemoved, err := removeAllSessionStates()
  1071→	if err != nil {
  1072→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
  1073→	} else if statesRemoved > 0 {
  1074→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
  1075→	}
  1076→
  1077→	// 4. Remove .entire/ directory
  1078→	if err := removeEntireDirectory(); err != nil {
  1079→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
  1080→	} else if entireDirExists {
  1081→		fmt.Fprintln(w, "  Removed .entire directory")
  1082→	}
  1083→
  1084→	// 5. Remove shadow branches
  1085→	branchesRemoved, err := removeAllShadowBranches()
  1086→	if err != nil {
  1087→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
  1088→	} else if branchesRemoved > 0 {
  1089→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
  1090→	}
  1091→
  1092→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
  1093→	return nil
  1094→}
